from fractions import Fraction
import math

def get_max_remaining_sum(M, idx, x_vals):
    current_x_vals = list(x_vals)
    res_sum = Fraction(0)
    for j in range(idx + 1, M + 1):
        x_prev = current_x_vals[-1]
        x_prev2 = current_x_vals[-2]
        min_x = math.ceil(1 + (x_prev**3 - x_prev**2) / x_prev2)
        current_x_vals.append(min_x)
        res_sum += Fraction(x_prev, min_x)
    return res_sum

def solve():
    target = Fraction(15, 16)
    all_solutions = []

    def backtrack(M, idx, current_sum, x_vals):
        if idx == M + 1:
            if current_sum == target:
                all_solutions.append((M, tuple(x_vals)))
            return

        if idx == M:
            rem = target - current_sum
            if rem > 0:
                num = rem.numerator
                den = rem.denominator
                if (x_vals[-1] * den) % num == 0:
                    xM = (x_vals[-1] * den) // num
                    min_x = 2
                    if idx > 1:
                        x_prev = x_vals[-1]
                        x_prev2 = x_vals[-2]
                        min_x = math.ceil(1 + (x_prev**3 - x_prev**2) / x_prev2)
                    if xM >= min_x:
                        backtrack(M, idx + 1, current_sum + Fraction(x_vals[-1], xM), x_vals + [xM])
            return

        if idx == 1:
            min_x = 2
        else:
            x_prev = x_vals[-1]
            x_prev2 = x_vals[-2]
            min_x = math.ceil(1 + (x_prev**3 - x_prev**2) / x_prev2)

        for x_val in range(min_x, 2000): # Tighten the limit for testing
            current_term = Fraction(x_vals[-1], x_val)
            if current_sum + current_term >= target:
                break
            max_sum = current_sum + current_term + get_max_remaining_sum(M, idx, x_vals + [x_val])
            if max_sum < target:
                break
            backtrack(M, idx + 1, current_sum + current_term, x_vals + [x_val])

    for M in range(1, 6):
        backtrack(M, 1, Fraction(0), [1])
    return all_solutions

